95	function markedSubclass(qualifiedName) {
96	  return class extends MarkedYAMLError {
97	    constructor(context, contextMark, problem, problemMark, note = null) {
98	      super(context, contextMark, problem, problemMark, note);
99	      this.qualifiedName = qualifiedName;
100	    }
101	  };
102	}
