// Port of PyYAML's resolver.py (BaseResolver + Resolver).
//
// Every implicit-resolver regex is replaced by a hand-written character
// scanner; the original PyYAML pattern (re.X whitespace stripped) sits in a
// comment above each one. The registration order below is PyYAML's own —
// bool, float, int, merge, null, timestamp, value, yaml — and resolve() walks
// the bucket for value[0] in exactly that order, so a value such as '1' hits
// the float matcher before the int matcher.

import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import { DIGITS, HEX_DIGITS, SPACES } from './chars.mjs';

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

const NON_ZERO_DIGITS = '123456789';
const SEXAGESIMAL_LEAD = '012345';
const DIGITS_ = DIGITS + '_';
const BINARY_ = '01_';
const OCTAL_ = '01234567_';
const HEX_DIGITS_ = HEX_DIGITS + '_';

// --- scanning primitives ---------------------------------------------------

/** The character at `i`, or '' past the end (never a member of a char set). */
const at = (s, i) => (i < s.length ? s[i] : '');

/** `ch` is one of `set` — guarding against the '' that `at` yields at EOS. */
const has = (set, ch) => ch !== '' && set.includes(ch);

/** `[-+]?` */
function optSign(s, i) {
  const ch = at(s, i);
  return (ch === '-' || ch === '+') ? i + 1 : i;
}

/** `[<set>]*` — greedy, never fails. */
function many(s, i, set) {
  let j = i;
  while (j < s.length && set.includes(s[j])) j += 1;
  return j;
}

/** Exactly `n` digits, or -1. */
function fixedDigits(s, i, n) {
  for (let k = 0; k < n; k += 1) if (!has(DIGITS, at(s, i + k))) return -1;
  return i + n;
}

/** `[0-9][0-9]?`, or -1. Greedy is safe: every follower here is a non-digit. */
function shortDigits(s, i) {
  if (!has(DIGITS, at(s, i))) return -1;
  return has(DIGITS, at(s, i + 1)) ? i + 2 : i + 1;
}

/** `(?:[eE][-+][0-9]+)?` — the sign is mandatory, so '1.5e3' is NOT a float. */
function optExponent(s, i) {
  const ch = at(s, i);
  if (ch !== 'e' && ch !== 'E') return i;
  let j = i + 1;
  const sign = at(s, j);
  if (sign !== '-' && sign !== '+') return i;
  j += 1;
  if (!has(DIGITS, at(s, j))) return i;
  return many(s, j + 1, DIGITS);
}

/** `(?::[0-5]?[0-9])+` — returns the end index, or -1 if no group matched. */
function sexagesimalGroups(s, i) {
  let j = i;
  let count = 0;
  while (at(s, j) === ':') {
    let k = j + 1;
    if (!has(DIGITS, at(s, k))) break;
    if (SEXAGESIMAL_LEAD.includes(at(s, k)) && has(DIGITS, at(s, k + 1))) k += 2;
    else k += 1;
    j = k;
    count += 1;
  }
  return count > 0 ? j : -1;
}

// --- the implicit-resolver matchers ---------------------------------------

// tag:yaml.org,2002:bool
// ^(?:yes|Yes|YES|no|No|NO|true|True|TRUE|false|False|FALSE|on|On|ON|off|Off|OFF)$
const BOOL_VALUES = [
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
];
function matchBool(s) {
  return BOOL_VALUES.includes(s);
}

// tag:yaml.org,2002:float
// ^(?:[-+]?(?:[0-9][0-9_]*)\.[0-9_]*(?:[eE][-+][0-9]+)?
//    |\.[0-9][0-9_]*(?:[eE][-+][0-9]+)?
//    |[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
//    |[-+]?\.(?:inf|Inf|INF)
//    |\.(?:nan|NaN|NAN))$
// The second branch demands a digit immediately after the dot: the reference
// binary resolves '._' and '._5' as str, but '.5_' as float.

/** `[-+]?[0-9][0-9_]*\.[0-9_]*(?:[eE][-+][0-9]+)?` */
function floatAlt1(s) {
  let i = optSign(s, 0);
  if (!has(DIGITS, at(s, i))) return false;
  i = many(s, i + 1, DIGITS_);
  if (at(s, i) !== '.') return false;
  i = many(s, i + 1, DIGITS_);
  return optExponent(s, i) === s.length;
}

/** `\.[0-9][0-9_]*(?:[eE][-+][0-9]+)?` */
function floatAlt2(s) {
  if (at(s, 0) !== '.') return false;
  if (!has(DIGITS, at(s, 1))) return false;
  const i = many(s, 2, DIGITS_);
  return optExponent(s, i) === s.length;
}

/** `[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*` */
function floatAlt3(s) {
  let i = optSign(s, 0);
  if (!has(DIGITS, at(s, i))) return false;
  i = many(s, i + 1, DIGITS_);
  i = sexagesimalGroups(s, i);
  if (i < 0 || at(s, i) !== '.') return false;
  return many(s, i + 1, DIGITS_) === s.length;
}

/** `[-+]?\.(?:inf|Inf|INF)` */
function floatAlt4(s) {
  const i = optSign(s, 0);
  if (at(s, i) !== '.') return false;
  const rest = s.slice(i + 1);
  return rest === 'inf' || rest === 'Inf' || rest === 'INF';
}

/** `\.(?:nan|NaN|NAN)` */
function floatAlt5(s) {
  return s === '.nan' || s === '.NaN' || s === '.NAN';
}

function matchFloat(s) {
  return floatAlt1(s) || floatAlt2(s) || floatAlt3(s) || floatAlt4(s) || floatAlt5(s);
}

// tag:yaml.org,2002:int
// ^(?:[-+]?0b[0-1_]+
//    |[-+]?0[0-7_]+
//    |[-+]?(?:0|[1-9][0-9_]*)
//    |[-+]?0x[0-9a-fA-F_]+
//    |[-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+)$

/** `[-+]?0b[0-1_]+` */
function intAlt1(s) {
  let i = optSign(s, 0);
  if (at(s, i) !== '0' || at(s, i + 1) !== 'b') return false;
  i += 2;
  if (!has(BINARY_, at(s, i))) return false;
  return many(s, i + 1, BINARY_) === s.length;
}

/** `[-+]?0[0-7_]+` */
function intAlt2(s) {
  let i = optSign(s, 0);
  if (at(s, i) !== '0') return false;
  i += 1;
  if (!has(OCTAL_, at(s, i))) return false;
  return many(s, i + 1, OCTAL_) === s.length;
}

/** `[-+]?(?:0|[1-9][0-9_]*)` */
function intAlt3(s) {
  const i = optSign(s, 0);
  if (at(s, i) === '0') return i + 1 === s.length;
  if (!has(NON_ZERO_DIGITS, at(s, i))) return false;
  return many(s, i + 1, DIGITS_) === s.length;
}

/** `[-+]?0x[0-9a-fA-F_]+` */
function intAlt4(s) {
  let i = optSign(s, 0);
  if (at(s, i) !== '0' || at(s, i + 1) !== 'x') return false;
  i += 2;
  if (!has(HEX_DIGITS_, at(s, i))) return false;
  return many(s, i + 1, HEX_DIGITS_) === s.length;
}

/** `[-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+` */
function intAlt5(s) {
  let i = optSign(s, 0);
  if (!has(NON_ZERO_DIGITS, at(s, i))) return false;
  i = many(s, i + 1, DIGITS_);
  i = sexagesimalGroups(s, i);
  return i >= 0 && i === s.length;
}

function matchInt(s) {
  return intAlt1(s) || intAlt2(s) || intAlt3(s) || intAlt4(s) || intAlt5(s);
}

// tag:yaml.org,2002:merge — ^(?:<<)$
function matchMerge(s) {
  return s === '<<';
}

// tag:yaml.org,2002:null — ^(?:~|null|Null|NULL|)$
function matchNull(s) {
  return s === '~' || s === 'null' || s === 'Null' || s === 'NULL' || s === '';
}

// tag:yaml.org,2002:timestamp
// ^(?:[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]
//    |[0-9][0-9][0-9][0-9]-[0-9][0-9]?-[0-9][0-9]?
//     (?:[Tt]|[ \t]+)[0-9][0-9]?
//     :[0-9][0-9]:[0-9][0-9](?:\.[0-9]*)?
//     (?:[ \t]*(?:Z|[-+][0-9][0-9]?(?::[0-9][0-9])?))?)$

/** `[0-9]{4}-[0-9]{2}-[0-9]{2}` */
function timestampAlt1(s) {
  let i = fixedDigits(s, 0, 4);
  if (i < 0 || at(s, i) !== '-') return false;
  i = fixedDigits(s, i + 1, 2);
  if (i < 0 || at(s, i) !== '-') return false;
  i = fixedDigits(s, i + 1, 2);
  return i === s.length;
}

/** The full date-time branch. */
function timestampAlt2(s) {
  let i = fixedDigits(s, 0, 4);
  if (i < 0 || at(s, i) !== '-') return false;
  i = shortDigits(s, i + 1);
  if (i < 0 || at(s, i) !== '-') return false;
  i = shortDigits(s, i + 1);
  if (i < 0) return false;
  // (?:[Tt]|[ \t]+)
  const sep = at(s, i);
  if (sep === 'T' || sep === 't') i += 1;
  else if (has(SPACES, sep)) i = many(s, i + 1, SPACES);
  else return false;
  i = shortDigits(s, i);
  if (i < 0 || at(s, i) !== ':') return false;
  i = fixedDigits(s, i + 1, 2);
  if (i < 0 || at(s, i) !== ':') return false;
  i = fixedDigits(s, i + 1, 2);
  if (i < 0) return false;
  // (?:\.[0-9]*)?
  if (at(s, i) === '.') i = many(s, i + 1, DIGITS);
  // (?:[ \t]*(?:Z|[-+][0-9][0-9]?(?::[0-9][0-9])?))? — the whole group is
  // optional, so a failed timezone leaves `i` where the seconds ended.
  const j = many(s, i, SPACES);
  const tz = at(s, j);
  if (tz === 'Z') {
    i = j + 1;
  } else if (tz === '-' || tz === '+') {
    let k = shortDigits(s, j + 1);
    if (k >= 0) {
      if (at(s, k) === ':') {
        const m = fixedDigits(s, k + 1, 2);
        if (m >= 0) k = m;
      }
      i = k;
    }
  }
  return i === s.length;
}

function matchTimestamp(s) {
  return timestampAlt1(s) || timestampAlt2(s);
}

// tag:yaml.org,2002:value — ^(?:=)$
function matchValue(s) {
  return s === '=';
}

// tag:yaml.org,2002:yaml — ^(?:!|&|\*)$
function matchYaml(s) {
  return s === '!' || s === '&' || s === '*';
}

// --- registration ----------------------------------------------------------

// Python's `regexp.match(value)` against a pattern ending in `$`: `$` matches
// at the end of the string *or* just before a single trailing newline.
const anchored = (exact) => (value) =>
  exact(value) || (value.endsWith('\n') && exact(value.slice(0, -1)));

/** char -> ordered [{tag, match}]; key '' is the empty scalar, null the wildcard. */
const IMPLICIT_RESOLVERS = new Map();

function addImplicitResolver(tag, match, first) {
  const keys = first === null ? [null] : first;
  for (const ch of keys) {
    if (!IMPLICIT_RESOLVERS.has(ch)) IMPLICIT_RESOLVERS.set(ch, []);
    IMPLICIT_RESOLVERS.get(ch).push({ tag, match: anchored(match) });
  }
}

addImplicitResolver('tag:yaml.org,2002:bool', matchBool, [...'yYnNoOtTfF']);
addImplicitResolver('tag:yaml.org,2002:float', matchFloat, [...'-+0123456789.']);
addImplicitResolver('tag:yaml.org,2002:int', matchInt, [...'-+0123456789']);
addImplicitResolver('tag:yaml.org,2002:merge', matchMerge, ['<']);
addImplicitResolver('tag:yaml.org,2002:null', matchNull, ['~', 'n', 'N', '']);
addImplicitResolver('tag:yaml.org,2002:timestamp', matchTimestamp, [...'0123456789']);
addImplicitResolver('tag:yaml.org,2002:value', matchValue, ['=']);
// Documentation only: a plain scalar can never start with '!', '&' or '*'.
addImplicitResolver('tag:yaml.org,2002:yaml', matchYaml, [...'!&*']);

// --- the mixin -------------------------------------------------------------

export const ResolverMixin = (Base) => {
  class Resolver extends Base {
    constructor(...args) {
      super(...args);
      this.resolverExactPaths = [];
      this.resolverPrefixPaths = [];
    }

    descendResolver(currentNode, currentIndex) {
      if (this.yamlPathResolvers.length === 0) return;
      const exactPaths = new Map();
      const prefixPaths = [];
      if (currentNode) {
        const depth = this.resolverPrefixPaths.length;
        for (const entry of this.resolverPrefixPaths[depth - 1]) {
          if (this.checkResolverPrefix(depth, entry.path, entry.kind, currentNode, currentIndex)) {
            if (entry.path.length > depth) prefixPaths.push(entry);
            else exactPaths.set(entry.kind, entry.tag);
          }
        }
      } else {
        for (const entry of this.yamlPathResolvers) {
          if (entry.path.length === 0) exactPaths.set(entry.kind, entry.tag);
          else prefixPaths.push(entry);
        }
      }
      this.resolverExactPaths.push(exactPaths);
      this.resolverPrefixPaths.push(prefixPaths);
    }

    ascendResolver() {
      if (this.yamlPathResolvers.length === 0) return;
      this.resolverExactPaths.pop();
      this.resolverPrefixPaths.pop();
    }

    checkResolverPrefix(depth, path, kind, currentNode, currentIndex) {
      const [nodeCheck, indexCheck] = path[depth - 1];
      if (typeof nodeCheck === 'string') {
        if (currentNode.tag !== nodeCheck) return false;
      } else if (nodeCheck !== null) {
        if (!(currentNode instanceof nodeCheck)) return false;
      }
      if (indexCheck === true && currentIndex !== null) return false;
      if ((indexCheck === false || indexCheck === null) && currentIndex === null) return false;
      if (typeof indexCheck === 'string') {
        if (!(currentIndex instanceof ScalarNode && indexCheck === currentIndex.value)) return false;
      } else if (typeof indexCheck === 'number' || typeof indexCheck === 'bigint') {
        if (indexCheck !== currentIndex) return false;
      }
      return true;
    }

    resolve(kind, value, implicit) {
      if (kind === ScalarNode && implicit[0]) {
        let resolvers;
        if (value === '') resolvers = this.yamlImplicitResolvers.get('') || [];
        else resolvers = this.yamlImplicitResolvers.get(value[0]) || [];
        const wildcardResolvers = this.yamlImplicitResolvers.get(null) || [];
        for (const { tag, match } of [...resolvers, ...wildcardResolvers]) {
          if (match(value)) return tag;
        }
        implicit = implicit[1];
      }
      if (this.yamlPathResolvers.length !== 0) {
        const exactPaths = this.resolverExactPaths[this.resolverExactPaths.length - 1];
        if (exactPaths.has(kind)) return exactPaths.get(kind);
        if (exactPaths.has(null)) return exactPaths.get(null);
      }
      if (kind === ScalarNode) return this.DEFAULT_SCALAR_TAG;
      else if (kind === SequenceNode) return this.DEFAULT_SEQUENCE_TAG;
      else if (kind === MappingNode) return this.DEFAULT_MAPPING_TAG;
      return undefined;
    }
  }

  // PyYAML holds these as class attributes; the prototype is the closest thing.
  Resolver.prototype.yamlImplicitResolvers = IMPLICIT_RESOLVERS;
  // PyYAML keys yaml_path_resolvers by a (path, kind) tuple, which JS cannot
  // do; a list of {path, kind, tag} is the same information. Nothing in the
  // exercised subset calls add_path_resolver, so this stays empty and both
  // descendResolver and ascendResolver short-circuit to no-ops.
  Resolver.prototype.yamlPathResolvers = [];
  Resolver.prototype.DEFAULT_SCALAR_TAG = DEFAULT_SCALAR_TAG;
  Resolver.prototype.DEFAULT_SEQUENCE_TAG = DEFAULT_SEQUENCE_TAG;
  Resolver.prototype.DEFAULT_MAPPING_TAG = DEFAULT_MAPPING_TAG;
  return Resolver;
};
